func (l *Lobby) applyDynamicScaling() {
	l.mutex.Lock()
	defer l.mutex.Unlock()
	l.applyDynamicScalingLocked()
}

// applyDynamicScalingLocked contains the core logic for reward scaling and assumes the mutex is held.
func (l *Lobby) applyDynamicScalingLocked() {
	// Scaling is based on how full the faucet is relative to its target maximum
	if l.maxFaucetCapacity <= 0 {
		return
	}

	// PILLAR 2: Usable Liquidity.
	// The authoritative unreserved liquidity equals the physical vault balance minus the
	// 1.0 unit gas floor, all outstanding virtual reward liabilities (playerBalances),
	// Club treasuries, the currently committed tournament pot, and any reserved
	// pending payouts. This ensures the reward ratio correctly accounts for
	// committed funds during high-concurrency events like tournament finalization.
	//
	// THE LEDGER IS INTEGER (Architecture Ledger): all arithmetic below is uint64 MICRO.
	// The legacy float fields (faucetBalance, maxFaucetCapacity, Club.Treasury) are INPUTS
	// converted to micro ONCE at this boundary; the liquidity ratio is quantised to
	// PERMILLE and is the only thing a reward is ever computed from.
	const microPerUnit = uint64(1_000_000)
	const permilleOne = uint64(1000)
	const gasFloorMicro = uint64(1_000_000) // the 1.0 unit gas floor the vault keeps

	var totalLiabilitiesMicro uint64
	for _, bal := range l.playerBalances {
		totalLiabilitiesMicro += bal
	}

	// PILLAR 2: Phase 4 Expansion. Include non-crypto vouchers in total liabilities
	// to ensure reward scaling remains conservative and solvent.
	for _, stats := range l.leaderboard {
		totalLiabilitiesMicro += stats.ArenaVouchers
		for _, bounty := range stats.RecoveryBounties {
			totalLiabilitiesMicro += bounty
		}
		totalLiabilitiesMicro += stats.BountyHunterBondMicro
	}

	// A capacity above this cannot be scaled without overflowing uint64. Refusing is honest:
	// a nonsense capacity must never silently pay nonsense.
	const maxScalableCapacityMicro = uint64(1) << 53
	capacityMicro := uint64(l.maxFaucetCapacity * float64(microPerUnit))
	if capacityMicro == 0 || capacityMicro > maxScalableCapacityMicro {
		log.Printf("[ECONOMY] Dynamic scaling REFUSED: faucet capacity %d micro is out of range; rewards left unchanged.\n", capacityMicro)
		return
	}
	faucetMicro := uint64(l.faucetBalance * float64(microPerUnit))

	var clubsMicro uint64
	for _, club := range l.clubs {
		clubsMicro += uint64(club.Treasury * float64(microPerUnit))
	}

	// Committed tournament money, in the same integer unit as everything else.
	committedMicro := l.tournamentPotBonusMicro + l.pendingTournamentPayoutsMicro
	if l.tournament.Active {
		committedMicro += l.tournament.PotMicro
	}

	// unusable = gas floor + virtual liabilities + club treasuries + committed tournament money.
	unusableMicro := gasFloorMicro + totalLiabilitiesMicro + clubsMicro + committedMicro
	var usableMicro uint64
	if faucetMicro > unusableMicro {
		usableMicro = faucetMicro - unusableMicro
	}
	if usableMicro > capacityMicro {
		usableMicro = capacityMicro
	}

	// PERMILLE, integer division, clamped to [100, 1000] exactly as the float form was clamped
	// to [0.1, 1.0]. This is the ONE quantisation; nothing below is computed from a float.
	ratioPermille := usableMicro * permilleOne / capacityMicro
	if ratioPermille > permilleOne {
		ratioPermille = permilleOne
	}
	if ratioPermille < permilleOne/10 {
		ratioPermille = permilleOne / 10
	}

	// 1. Scale the primary base reward (integer permille of the integer liquidity ratio).
	l.baseReward = l.initialBaseReward * ratioPermille / permilleOne

	// 2. Iterate through the entire reward stack and scale based on unscaled initial values.
	// We clear the stack first to ensure assets removed from the template are purged.
	l.rewardStack = make(map[string]uint64)
	var rewardSum uint64
	for assetID, initialAmt := range l.initialRewards {
		scaledAmt := initialAmt * ratioPermille / permilleOne
		l.rewardStack[assetID] = scaledAmt
		rewardSum += scaledAmt
	}

	// PILLAR 2: Safety Cap Alignment.
	// Ensure the sum of un-boosted base rewards does not exceed 50% of the MaxSinglePayoutMicro.
	// This reserves headroom for Reputation multipliers, Bounties, and Virtual Balances (Salaries/Heists).
	const rewardSafetyLimit = MaxSinglePayoutMicro / 2
	if rewardSum > rewardSafetyLimit {
		log.Printf("[ECONOMY WARNING] Aggregated base rewards (%d) exceed safety limit (%d). Clamping stack to preserve headroom.\n", rewardSum, rewardSafetyLimit)
		// Integer clamp: the allowed share as PERMILLE of the current sum, so the multiplication
		// cannot overflow uint64 and no float ever enters a reward.
		clampPermille := rewardSafetyLimit * permilleOne / rewardSum
		for assetID, scaled := range l.rewardStack {
			l.rewardStack[assetID] = scaled * clampPermille / permilleOne
		}
		// Sync the legacy baseReward field
		l.baseReward = l.rewardStack[l.rewardAssetID]
	}

	// DISPLAY ONLY: the UI reads a ratio, derived from the integer owner above. It never feeds a payout.
	l.RewardRatio = float64(ratioPermille) / float64(permilleOne)

	log.Printf("[ECONOMY] Dynamic Scaling Applied (Ratio: %d permille). Faucet Capacity: %.2f units.\n", ratioPermille, l.faucetBalance)
}

// saveSeasonMetadataLocked persists the current season state and reward configuration to disk.
// This function assumes the Lobby mutex is already held.
func (l *Lobby) saveSeasonMetadataLocked() {
	// PILLAR 6: Blockchain Persistence.
	// Local file persistence is deprecated. Economy metadata is now
	// part of the authoritative VBT_ECONOMY_SNAPSHOT.
	// We trigger the snapshot logic immediately using the current locked state.
	state := struct {
		Balances     map[string]uint64       `json:"balances"`
		Kidnappings  map[int]KidnapState     `json:"active_kidnappings"`
		MatchHistory map[string]MatchHistory `json:"match_history"`
		Tournament   TournamentState         `json:"tournament"`
		SeasonNum    int                     `json:"season_num"`
		SeasonStart  time.Time               `json:"season_start"`
		MarketNodes  map[string]EntityMarketNode `json:"market_nodes"` // PILLAR 2: AMM State
		Rewards      map[string]uint64       `json:"initial_rewards"`
		RewardTokens map[string]RewardToken  `json:"reward_tokens"` // The registry descriptor behind each template entry
	}{
		Balances:     l.playerBalances,
		Kidnappings:  l.activeKidnappings,
		MatchHistory: l.matchHistory,
		Tournament:   l.tournament,
		SeasonNum:    l.seasonNumber,
		SeasonStart:  l.seasonStart,
		MarketNodes:  make(map[string]EntityMarketNode),
		Rewards:      l.initialRewards,
		RewardTokens: l.rewardTokens,
		}

	// Deep copy AMM state for snapshotting.
	//
	// THE ROUTER'S LOCK, because the map's ONE owner mutex is the router's: `l.marketNodes` and
	// `l.tokenSinkRouter.MarketNodes` are THE SAME map, and the trade path INSERTS into it under that
	// lock. The lobby lock this function is called under does not exclude a router-side reader or
	// writer, and a map walk concurrent with a write is a `fatal error` Go lets nothing recover from.
	for _, ref := range l.tokenSinkRouter.marketNodeRefs() {
		node := ref.Node
		state.MarketNodes[ref.EntityID] = *node
	}

	// PILLAR 2: Ledger Integrity.
	// Since we are already holding the mutex, we dispatch the snapshot note
	// via the internal helper which is goroutine-safe.
	// ONE RECORD PER CADENCE instead of one per family (A5, plan 15): one fee, one nonce stream, and
	// the SAME held lock. The batch IS the writer for these three families, and the census gate knows
	// that: it counts a family key named beside saveRecordBatchLocked as written.
	// fenced_listings IS NOT A LOBBY-OWNED MAP: its owner mutex is fencedListingsMu, so the copy is
	// taken under THAT lock and RELEASED before the batch sees it. Marshalling it under the lobby lock
	// would race the fence marketplace - the aliased-map hazard, one owner per map.
	fenced := make(map[string]FenceListing, len(l.fencedListings))
	func() {
		l.fencedListingsMu.RLock()
		defer l.fencedListingsMu.RUnlock()
		for id, listing := range l.fencedListings {
			fenced[id] = listing
		}
	}()
		if recordsDispatchEnabled() {
		// rivalries IS NOT A LOBBY-OWNED MAP: it lives in the RivalryEngine beside its OWN Mu, so the copy
	// is taken under THAT lock, DEEP-COPIED, and released before the batch sees it - a pointer copy
	// would still be a live object.
	var rivalries map[string]*RegionRivalry
	if l.rivalryEngine != nil {
		rivalries = make(map[string]*RegionRivalry)
		func() {
			l.rivalryEngine.Mu.RLock()
			defer l.rivalryEngine.Mu.RUnlock()
			for id, rv := range l.rivalryEngine.Rivalries {
				cp := *rv
				rivalries[id] = &cp
			}
		}()
	}
		l.saveRecordBatchLocked(map[string]any{
			"economy":           state,
			"leaderboard":       l.leaderboard,
			"onboarded_wallets": l.onboardedWallets,
			"clubs":             l.clubs,
			"loans":             l.loans,
			"auctions":          l.auctions,
			"pets":              l.pets,
			"vehicles":          l.vehicles,
			"world_content":     l.worldContent,
			"match_history":     l.matchHistory,
			"fenced_listings":   fenced,
			"entity_market":     state.MarketNodes,
			"rivalries":         rivalries,
		})
	}
	log.Printf("[ECONOMY] Season metadata (%d) queued for blockchain persistence.\n", l.seasonNumber)
}

